// Constexpr O(log N) binary-search lookup returning nullptr if unrecognized.
constexpr const Instruction* findInstruction(std::string_view name) {
    const auto* it = std::lower_bound(
        kInstructions.begin(), kInstructions.end(), name, [](const Instruction& inst, std::string_view key) {
            return inst.name < key;
        });
    if (it != kInstructions.end() && it->name == name) {
        return it;
    }
    return nullptr;
}

